# CTTIR Material Atlas v3.1. Source this file from the extracted project folder.
# All artwork is generated by the bundled R packages grid and grDevices.
.cttir_source <- tryCatch(base::sys.frame(1)$ofile,error=function(e)NULL)
.cttir_rdir <- if(!base::is.null(.cttir_source)) base::dirname(base::normalizePath(.cttir_source)) else "R"
# On Linux, use bundled fonts with neutral smoothing before opening devices.
# Set CTTIR_FONTCONFIG=system before sourcing to retain your own fontconfig.
.cttir_fc <- base::file.path(base::dirname(.cttir_rdir),"fonts","fontconfig-linux.conf")
if(base::Sys.info()[["sysname"]]=="Linux" && base::Sys.getenv("CTTIR_FONTCONFIG","auto")=="auto" &&
   base::file.exists(.cttir_fc)) base::Sys.setenv(FONTCONFIG_FILE=base::normalizePath(.cttir_fc))
for(.f in c("accessibility.R","palette.R","primitives.R","motifs.R"))
  base::source(base::file.path(.cttir_rdir,.f),local=FALSE)
base::rm(.f,.cttir_source,.cttir_rdir,.cttir_fc)

# Fit exact names with device font metrics; never stretch or break the wordmark.
cttir_name <- function(name,y=.241,max_width=.74,size=38,colour="#F4F8FC",font="Inter") {
  repeat {
    g<-grid::textGrob(name,gp=grid::gpar(fontfamily=font,fontface=2,fontsize=size))
    if(grid::convertWidth(grid::grobWidth(g),"npc",valueOnly=TRUE)<=max_width || size<=17) break
    size<-size-.25
  }
  grid::grid.text(name,.5,y,gp=grid::gpar(fontfamily=font,fontface=2,fontsize=size,col=colour))
  base::invisible(size)
}

cttir_draw <- function(name,family,mode="primary",symbol_only=FALSE,
  font=base::Sys.getenv("CTTIR_FONT","Inter"),newpage=TRUE) {
  if(newpage) grid::grid.newpage()
  sc<-grid::convertWidth(grid::unit(1,"npc"),"inches",valueOnly=TRUE)/6
  grid::pushViewport(grid::viewport(gp=grid::gpar(cex=sc,lex=sc)))
  base::on.exit(grid::popViewport(),add=TRUE)
  s<-cttir_style(family,mode)
  hex<-function(r,fill,col=NA,lwd=1) grid::grid.polygon(
    .5+c(0,r,r,0,-r,-r),.5+c(r,r/2,-r/2,-r,-r/2,r/2),
    gp=grid::gpar(fill=fill,col=col,lwd=lwd,linejoin="round"))
  # A clean sticker edge and fine material keyline survive busy backgrounds.
  hex(.490,"#FFFFFF");hex(.478,s$rim);hex(.470,s$face)
  if(!symbol_only) {
    grid::grid.polygon(c(.5,.970,.970,.5),c(.970,.735,.49,.70),
      gp=grid::gpar(fill=s$facet,col=NA))
    grid::grid.polygon(c(.030,.5,.5,.030),c(.265,.49,.70,.735),
      gp=grid::gpar(fill=s$facet2,col=NA))
    grid::grid.polygon(c(.030,.5,.970,.5),c(.265,.38,.265,.030),
      gp=grid::gpar(fill=s$face,col=NA))
    grid::grid.text("C T T I R",.5,.864,gp=grid::gpar(fontfamily=font,
      fontface=2,fontsize=12,col=s$muted))
    # A compact label shelf gives each wordmark a consistent visual baseline.
    grid::grid.lines(c(.19,.81),c(.300,.300),gp=grid::gpar(col=cttir_alpha(s$rim,.42),lwd=1))
    grid::grid.lines(c(.465,.535),c(.300,.300),gp=grid::gpar(col=s$rim,lwd=4,lineend="round"))
    cttir_name(name,.241,size=if(name=="CTTIR")46 else 38,colour=s$ink,font=font)
    descriptor<-if(name=="hyperloom")"HYPERSPECTRAL SUITE" else
      if(name=="phenoloom")"SPATIAL BIOLOGY SUITE" else cttir_family_labels[[family]]
    grid::grid.text(descriptor,.5,.159,
      gp=grid::gpar(fontfamily=font,fontsize=10.3,fontface=2,col=s$muted))
  }
  size<-if(symbol_only).86 else .68
  grid::pushViewport(grid::viewport(x=.5,y=if(symbol_only).5 else .575,
    width=size,height=size*base::sqrt(3)/2))
  cttir_motif(name,s,small=symbol_only)
  grid::popViewport()
  base::invisible(NULL)
}

# Every device is explicitly closed, even if a drawing fails.
cttir_device <- function(open_device,draw) {
  open_device();base::on.exit(grDevices::dev.off(),add=TRUE);draw()
  base::invisible(NULL)
}
cttir_render <- function(name,family,outdir,width=1600L,
  font=base::Sys.getenv("CTTIR_FONT","Inter")) {
  base::dir.create(outdir,recursive=TRUE,showWarnings=FALSE)
  ratio<-base::sqrt(3)/2;hh<-base::round(width/ratio)
  for(mode in c("primary","light","mono")) {
    stem<-if(mode=="primary")"logo" else base::paste0("logo-",mode)
    cttir_device(function()grDevices::svg(base::file.path(outdir,base::paste0(stem,".svg")),
      width=6,height=6/ratio,bg="transparent",family=font),function()cttir_draw(name,family,mode,font=font))
    cttir_device(function()grDevices::png(base::file.path(outdir,base::paste0(stem,".png")),
      width=width,height=hh,res=width/6,bg="transparent",type="cairo",antialias="gray"),function()cttir_draw(name,family,mode,font=font))
  }
  cttir_device(function()grDevices::cairo_pdf(base::file.path(outdir,"logo.pdf"),
    width=6,height=6/ratio,bg="transparent",family=font),function()cttir_draw(name,family,font=font))
  cttir_device(function()grDevices::svg(base::file.path(outdir,"logo-symbol.svg"),
    width=6,height=6/ratio,bg="transparent",family=font),function()cttir_draw(name,family,symbol_only=TRUE,font=font))
  for(px in c(32L,48L,64L,128L,256L)) cttir_device(function()
    grDevices::png(base::file.path(outdir,base::paste0("icon-",px,".png")),
      width=px,height=px,res=px/6,bg="transparent",type="cairo",antialias="gray"),function() {
        grid::grid.newpage();grid::pushViewport(grid::viewport(width=ratio,height=1))
        cttir_draw(name,family,symbol_only=TRUE,font=font,newpage=FALSE);grid::popViewport()
      })
  base::invisible(outdir)
}
cttir_render_package <- function(name,root=".") {
  registry<-utils::read.csv(base::file.path(root,"packages.csv"),stringsAsFactors=FALSE)
  row<-registry[registry$name==name,,drop=FALSE]
  if(base::nrow(row)!=1L)base::stop("Unknown identity: ",name)
  cttir_render(name,row$family,base::file.path(root,"logos",name))
}
